import{_ as a,c as t,o,af as i}from"./chunks/framework.J4isc1KJ.js";const p=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),r={name:"guide/index.md"};function l(n,e,s,d,c,h){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p>SilenceUI 是一套面向后台管理系统的 Web Components 组件库，基于 Lit 3 与 TypeScript 构建。组件注册为标准 Custom Elements，可在 Vue、React、Angular、原生 HTML 等宿主环境中使用。</p><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><strong>跨框架</strong>：对外暴露标准 HTML 标签，不绑定具体框架运行时。</li><li><strong>后台优先</strong>：覆盖表单、表格、导航、反馈、布局和数据展示等管理系统高频场景。</li><li><strong>主题可控</strong>：通过 CSS 变量统一管理 design token，支持明暗模式和运行时换肤。</li><li><strong>类型友好</strong>：包入口导出组件类、主题 API 与命令式消息 API 的类型声明。</li><li><strong>事件一致</strong>：组件自定义事件使用 <code>CustomEvent</code>，业务数据统一放在 <code>detail</code>。</li></ul><h2 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to &quot;兼容性&quot;">​</a></h2><p>支持所有现代浏览器：</p><ul><li>Chrome &gt;= 60</li><li>Firefox &gt;= 63</li><li>Safari &gt;= 11</li><li>Edge &gt;= 79</li></ul><h2 id="为什么选择-silenceui" tabindex="-1">为什么选择 SilenceUI？ <a class="header-anchor" href="#为什么选择-silenceui" aria-label="Permalink to &quot;为什么选择 SilenceUI？&quot;">​</a></h2><h3 id="轻量高效" tabindex="-1">轻量高效 <a class="header-anchor" href="#轻量高效" aria-label="Permalink to &quot;轻量高效&quot;">​</a></h3><p>基于浏览器原生 Custom Elements 与 Shadow DOM，组件内部样式默认隔离，接入侧只需要引入一次包入口。</p><h3 id="开箱即用" tabindex="-1">开箱即用 <a class="header-anchor" href="#开箱即用" aria-label="Permalink to &quot;开箱即用&quot;">​</a></h3><p>入口文件会注册全部组件，并自动恢复持久化的主题配置。引入后即可在页面中使用 <code>su-</code> / <code>se-</code> 标签。</p><h3 id="跨框架兼容" tabindex="-1">跨框架兼容 <a class="header-anchor" href="#跨框架兼容" aria-label="Permalink to &quot;跨框架兼容&quot;">​</a></h3><p>简单属性通过 HTML attribute 传递，数组、对象、函数等复杂数据通过 DOM property 传递。Vue 与 React 的接入注意事项见<a href="./getting-started.html">快速开始</a>。</p><h3 id="主题定制" tabindex="-1">主题定制 <a class="header-anchor" href="#主题定制" aria-label="Permalink to &quot;主题定制&quot;">​</a></h3><p>所有主题色来自 <code>styles/theme.css</code> 的 CSS 变量，可静态覆盖，也可通过 <code>setThemeColors</code> 在运行时切换。</p>',16)]))}const m=a(r,[["render",l]]);export{p as __pageData,m as default};
